exercises.solution:
export function hotShardQps(totalQps, shards, hotKeyPermille) {
  const hot = (totalQps * hotKeyPermille) / 1000;
  const rest = (totalQps * (1000 - hotKeyPermille)) / 1000;
  return hot + rest / shards;
}

export function skewPermille(totalQps, shards, hotKeyPermille) {
  return (hotShardQps(totalQps, shards, hotKeyPermille) * 1000) / (totalQps / shards);
}

