exercises.solution:
export function bytesToMove(totalBytes, oldShards, newShards) {
  return (totalBytes * (newShards - oldShards)) / newShards;
}

export function rebalanceSeconds(bytesToMove, mbPerSec) {
  return bytesToMove / (mbPerSec * 1000000);
}

