exercises.solution:
export function shardQueriesPerSec(apiQps, shards, keyedPermille) {
  return (apiQps * (keyedPermille * 1 + (1000 - keyedPermille) * shards)) / 1000;
}

export function queriesSavedPerSec(apiQps, shards, keyedPermille) {
  return apiQps * shards - shardQueriesPerSec(apiQps, shards, keyedPermille);
}

